export function receiptLines(order: Order, code: string): string[] {
  if (order.items.length === 0) {
    throw new Error(`order ${order.id} has no items`);
  }
  const lines: string[] = [];
  let subtotal = 0;
  for (const item of order.items) {
    if (item.quantity <= 0) {
      throw new Error(`order ${order.id}: bad quantity for ${item.sku}`);
    }
    const amount = item.quantity * item.unitPrice;
    subtotal += amount;
    lines.push(`${item.name} x${item.quantity}  ${amount.toFixed(2)}`);
  }
  lines.push(`Subtotal  ${subtotal.toFixed(2)}`);
  const rate = DISCOUNTS[code] ?? 0;
  const discount = Math.round(subtotal * rate * 100) / 100;
  if (discount > 0) {
    lines.push(`Discount ${code}  -${discount.toFixed(2)}`);
  } else if (code !== "") {
    lines.push(`Code ${code} does not apply`);
  }
  const taxable = subtotal - discount;
  const tax = Math.round(taxable * TAX_RATES[order.region] * 100) / 100;
  lines.push(`Tax ${order.region}  ${tax.toFixed(2)}`);
  lines.push(`Total  ${(taxable + tax).toFixed(2)}`);
  return lines;
}

