export function receiptLines(order: Order, code: string): string[] {
  const subtotal = subtotalOf(order);
  const discount = cents(subtotal * (DISCOUNTS[code] ?? 0));
  const tax = cents((subtotal - discount) * TAX_RATES[order.region]);
  return [
    ...order.items.map((item) => `${item.name} x${item.quantity}  ${(item.quantity * item.unitPrice).toFixed(2)}`),
    `Subtotal  ${subtotal.toFixed(2)}`,
    ...discountLines(code, discount),
    `Tax ${order.region}  ${tax.toFixed(2)}`,
    `Total  ${(subtotal - discount + tax).toFixed(2)}`,
  ];
}

function subtotalOf(order: Order): number {
  if (order.items.length === 0) {
    throw new Error(`order ${order.id} has no items`);
  }
  let subtotal = 0;
  for (const item of order.items) {
    if (item.quantity <= 0) {
      throw new Error(`order ${order.id}: bad quantity for ${item.sku}`);
    }
    subtotal += item.quantity * item.unitPrice;
  }
  return subtotal;
}

function discountLines(code: string, discount: number): string[] {
  if (discount > 0) {
    return [`Discount ${code}  -${discount.toFixed(2)}`];
  }
  return code === "" ? [] : [`Code ${code} does not apply`];
}

function cents(amount: number): number {
  return Math.round(amount * 100) / 100;
}
